xpath.script:
(function() {
    let currentStep = 1;
    const totalSteps = 5;
    let isSubmitting = false;

    function updateProgressBar(step) {
        const percentage = (step / totalSteps) * 100;
        const progressBar = document.getElementById('mainProgressBar');
        const percentageText = document.getElementById('progressPercentage');
        if (progressBar) progressBar.style.width = percentage + '%';
        if (percentageText) percentageText.textContent = Math.round(percentage) + '%';
    }

    function updateStepsUI(step) {
        const stepItems = document.querySelectorAll('.step-item');
        for (let i = 0; i < stepItems.length; i++) {
            const item = stepItems[i];
            const stepNum = parseInt(item.getAttribute('data-step'));
            if (stepNum === step) {
                item.classList.add('active');
                item.classList.remove('completed');
            } else if (stepNum < step) {
                item.classList.add('completed');
                item.classList.remove('active');
            } else {
                item.classList.remove('active', 'completed');
            }
        }
        updateProgressBar(step);
    }

    function showLoadingOverlay() {
        var overlay = document.getElementById('msf-loading-overlay');
        if (overlay) {
            overlay.style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }
    }

    function showStep(step) {
        var steps = document.querySelectorAll('.msf-step');
        for (var i = 0; i < steps.length; i++) {
            steps[i].classList.remove('active-step');
        }
        var currentStepEl = document.querySelector('.msf-step[data-step="' + step + '"]');
        if (currentStepEl) currentStepEl.classList.add('active-step');

        updateStepsUI(step);

        var prevBtn = document.getElementById('prevBtn');
        var nextBtn = document.getElementById('nextBtn');
        var submitBtn = document.getElementById('submitBtn');

        if (prevBtn) prevBtn.style.display = step === 1 ? 'none' : 'inline-block';
        if (nextBtn && submitBtn) {
            if (step === totalSteps) {
                nextBtn.style.display = 'none';
                submitBtn.style.display = 'inline-block';
            } else {
                nextBtn.style.display = 'inline-block';
                submitBtn.style.display = 'none';
            }
        }

        var container = document.querySelector('.msf-container');
        if (container) container.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function validateStep(step) {
        var stepContainer = document.querySelector('.msf-step[data-step="' + step + '"]');
        if (!stepContainer) return true;

        var requiredFields = stepContainer.querySelectorAll('[required]');
        var isValid = true;

        for (var i = 0; i < requiredFields.length; i++) {
            var field = requiredFields[i];
            if (!field) continue;

            var degreeContainer = document.getElementById('degree_field_container');
            if (field.id === 'type_id' && degreeContainer && degreeContainer.style.display === 'none') {
                continue;
            }

            if (field.id === 'lecturer_end_date') {
                var currentlyWorking = document.getElementById('currently_working');
                if (currentlyWorking && currentlyWorking.checked) continue;
            }

            try {
                if (field.type === 'checkbox') {
                    if (!field.checked && field.id !== 'currently_working' && field.id !== 'is_document_approved') {
                        isValid = false;
                        field.classList.add('is-invalid');
                    } else if (field.classList) {
                        field.classList.remove('is-invalid');
                    }
                } else {
                    if (!field.value || !field.value.trim()) {
                        isValid = false;
                        if (field.classList) field.classList.add('is-invalid');
                    } else {
                        if (field.classList) field.classList.remove('is-invalid');
                    }
                }
            } catch(e) {
                console.warn('Error validating field:', field.id, e);
            }
        }

        if (step === 5) {
            var declarationCheck = document.getElementById('declaration_check');
            if (declarationCheck && !declarationCheck.checked) {
                isValid = false;
                declarationCheck.classList.add('is-invalid');
            } else if (declarationCheck && declarationCheck.classList) {
                declarationCheck.classList.remove('is-invalid');
            }
        }

        return isValid;
    }

    window.changeStep = function(direction) {
        if (direction === 1) {
            if (!validateStep(currentStep)) return;
            currentStep++;
        } else if (direction === -1) {
            currentStep--;
        }
        if (currentStep >= 1 && currentStep <= totalSteps) showStep(currentStep);
    };

    function getSelectedSkills() {
        var selected = [];
        var skillCheckboxes = document.querySelectorAll('.computer-skill');
        for (var i = 0; i < skillCheckboxes.length; i++) {
            if (skillCheckboxes[i] && skillCheckboxes[i].checked) {
                selected.push(parseInt(skillCheckboxes[i].value));
            }
        }
        return selected;
    }

    // Function to update form data with user entered values
    function updateFormData(form) {
        // Get values from our multi-step form fields
        var firstName = document.getElementById('partner_name');
        var lastName = document.getElementById('last_name');
        var phone = document.getElementById('partner_phone');
        var mobile = document.getElementById('partner_mobile');
        var email = document.getElementById('partner_email');

        // Merge first name and last name into full name
        var fullName = '';
        if (firstName && firstName.value) {
            fullName = firstName.value;
            if (lastName && lastName.value) {
                fullName += ' ' + lastName.value;
            }
        }

        // Find the original name field in the form and update it
        var originalNameField = form.querySelector('input[name="partner_name"]');
        if (originalNameField && fullName) {
            originalNameField.value = fullName;
            console.log('Updated partner_name to:', fullName);
        }

        // Also update the hidden name field if it exists
        var hiddenNameField = document.getElementById('applicant_name_hidden');
        if (hiddenNameField && fullName) {
            hiddenNameField.value = fullName;
            console.log('Updated applicant_name_hidden to:', fullName);
        }

        // Update phone number if user entered a value
        if (phone && phone.value) {
            var originalPhoneField = form.querySelector('input[name="partner_phone"]');
            if (originalPhoneField) {
                originalPhoneField.value = phone.value;
                console.log('Updated partner_phone to:', phone.value);
            }
        }

        // Update mobile number if user entered a value
        if (mobile && mobile.value) {
            var originalMobileField = form.querySelector('input[name="partner_mobile"]');
            if (originalMobileField) {
                originalMobileField.value = mobile.value;
                console.log('Updated partner_mobile to:', mobile.value);
            }
        }

        // Update email if user entered a value
        if (email && email.value) {
            var originalEmailField = form.querySelector('input[name="partner_email"]');
            if (originalEmailField) {
                originalEmailField.value = email.value;
                console.log('Updated partner_email to:', email.value);
            }
        }
    }

    function setupFormSubmit(form) {
        if (!form) return;

        var submitBtn = document.getElementById('submitBtn');
        if (!submitBtn) return;

        // Remove any existing click handlers to avoid duplicates
        var newSubmitBtn = submitBtn.cloneNode(true);
        submitBtn.parentNode.replaceChild(newSubmitBtn, submitBtn);
        submitBtn = newSubmitBtn;

        submitBtn.addEventListener('click', function(e) {
            console.log('Submit button clicked - validating');

            if (!validateStep(currentStep)) {
                showStep(currentStep);
                e.preventDefault();
                e.stopPropagation();
                return false;
            }

            // Update form data with user entered values BEFORE submission
            updateFormData(form);

            // Add hidden field for skills
            var existingHidden = form.querySelector('input[name="computer_skill_ids"][type="hidden"]');
            if (!existingHidden) {
                var selectedSkills = getSelectedSkills();
                var hiddenInput = document.createElement('input');
                hiddenInput.type = 'hidden';
                hiddenInput.name = 'computer_skill_ids';
                hiddenInput.value = selectedSkills.length > 0 ? JSON.stringify([[6, 0, selectedSkills]]) : JSON.stringify([[5, 0, 0]]);
                form.appendChild(hiddenInput);
            }

            // Disable skills checkboxes
            var skillCheckboxes = document.querySelectorAll('.computer-skill');
            for (var i = 0; i < skillCheckboxes.length; i++) {
                if (skillCheckboxes[i]) skillCheckboxes[i].disabled = true;
            }

            // Show loader and disable button
            setTimeout(function() {
                showLoadingOverlay();
                submitBtn.disabled = true;
                submitBtn.innerHTML = 'Submitting...';

                var prevBtn = document.getElementById('prevBtn');
                var nextBtn = document.getElementById('nextBtn');
                if (prevBtn) prevBtn.disabled = true;
                if (nextBtn) nextBtn.disabled = true;
            }, 10);

            console.log('Allowing natural form submission');
            return true;
        });
    }

    // Initialize the application
    document.addEventListener('DOMContentLoaded', function() {
        var prevBtn = document.getElementById('prevBtn');
        var nextBtn = document.getElementById('nextBtn');

        if (prevBtn) prevBtn.onclick = function() { changeStep(-1); };
        if (nextBtn) nextBtn.onclick = function() { changeStep(1); };

        var stepItems = document.querySelectorAll('.step-item');
        for (var i = 0; i < stepItems.length; i++) {
            var item = stepItems[i];
            if (item) {
                item.addEventListener('click', function() {
                    var targetStep = parseInt(this.getAttribute('data-step'));
                    var canNavigate = true;
                    for (var s = 1; s < targetStep; s++) {
                        if (!validateStep(s)) {
                            canNavigate = false;
                            showStep(s);
                            break;
                        }
                    }
                    if (canNavigate && targetStep !== currentStep) {
                        currentStep = targetStep;
                        showStep(currentStep);
                    }
                });
            }
        }

        // Function to handle name merging in real-time
        function setupNameMerging() {
            var firstName = document.getElementById('partner_name');
            var lastName = document.getElementById('last_name');
            var nameHidden = document.getElementById('applicant_name_hidden');

            function mergeNames() {
                if (firstName && nameHidden) {
                    var fullName = firstName.value || '';
                    if (lastName && lastName.value) {
                        fullName += (fullName ? ' ' : '') + lastName.value;
                    }
                    nameHidden.value = fullName;
                }
            }

            if (firstName) {
                firstName.addEventListener('input', mergeNames);
            }
            if (lastName) {
                lastName.addEventListener('input', mergeNames);
            }
            mergeNames(); // Initial merge
        }

        setupNameMerging();

        // Age calculation
        var dobField = document.getElementById('date_of_birth');
        var ageField = document.getElementById('age_display');
        if (dobField && ageField) {
            var calculateAge = function() {
                if (!dobField.value) {
                    if (ageField) ageField.value = '';
                    return;
                }
                var birth = new Date(dobField.value);
                var now = new Date();
                var years = now.getFullYear() - birth.getFullYear();
                if (now.getMonth() < birth.getMonth() || (now.getMonth() === birth.getMonth() && now.getDate() < birth.getDate())) {
                    years--;
                }
                if (ageField) ageField.value = (years > 0 ? years : 0) + ' years';
            };
            dobField.onchange = calculateAge;
            dobField.oninput = calculateAge;
            calculateAge();
        }

        // Lecturer Duration Calculation
        var start = document.getElementById('lecturer_time');
        var end = document.getElementById('lecturer_end_date');
        var checkbox = document.getElementById('currently_working');
        var display = document.getElementById('lecturer_duration_display');

        function calculateDuration() {
            if (!start || !display) return;
            if (!start.value) {
                if (display) display.value = '';
                return;
            }
            var startDate = new Date(start.value);
            var endDate;
            var isPresent = false;

            if (checkbox && checkbox.checked) {
                endDate = new Date();
                isPresent = true;
                if (end) {
                    end.disabled = true;
                    end.value = '';
                }
            } else {
                if (end) {
                    end.disabled = false;
                    if (!end.value) {
                        if (display) display.value = 'Please select end date';
                        return;
                    }
                    endDate = new Date(end.value);
                }
            }

            if (startDate > endDate) {
                if (display) display.value = 'Invalid dates';
                return;
            }

            var years = endDate.getFullYear() - startDate.getFullYear();
            var months = endDate.getMonth() - startDate.getMonth();
            var days = endDate.getDate() - startDate.getDate();

            if (days < 0) {
                months--;
                days += new Date(endDate.getFullYear(), endDate.getMonth(), 0).getDate();
            }
            if (months < 0) {
                years--;
                months += 12;
            }

            var result = [];
            if (years > 0) result.push(years + ' year' + (years !== 1 ? 's' : ''));
            if (months > 0) result.push(months + ' month' + (months !== 1 ? 's' : ''));
            if (days > 0 && years === 0 && months === 0) result.push(days + ' day' + (days !== 1 ? 's' : ''));

            if (display) {
                if (result.length) {
                    display.value = result.join(' ');
                    if (isPresent) display.value += ' (Present)';
                } else {
                    display.value = 'Less than a day';
                    if (isPresent) display.value += ' (Present)';
                }
            }
        }

        if (checkbox) {
            if (checkbox.checked && end) {
                end.disabled = true;
                end.value = '';
            }
            checkbox.addEventListener('change', function() {
                if (this.checked) {
                    if (end) {
                        end.disabled = true;
                        end.value = '';
                    }
                } else {
                    if (end) end.disabled = false;
                }
                calculateDuration();
            });
        }

        if (start) start.addEventListener('change', calculateDuration);
        if (end) end.addEventListener('change', calculateDuration);
        calculateDuration();

        // Document Approval - Show/Hide Degree Field
        var docCheckbox = document.getElementById('is_document_approved');
        var degreeContainer = document.getElementById('degree_field_container');
        var degreeSelect = document.getElementById('type_id');

        if (docCheckbox && degreeContainer && degreeSelect) {
            if (docCheckbox.checked) {
                degreeContainer.style.display = 'block';
                degreeSelect.setAttribute('required', 'required');
            } else {
                degreeContainer.style.display = 'none';
                degreeSelect.removeAttribute('required');
                degreeSelect.value = '';
            }
            docCheckbox.addEventListener('change', function() {
                if (this.checked) {
                    degreeContainer.style.display = 'block';
                    degreeSelect.setAttribute('required', 'required');
                } else {
                    degreeContainer.style.display = 'none';
                    degreeSelect.removeAttribute('required');
                    degreeSelect.value = '';
                }
            });
        }

        // Skills badges handler
        var skillBadges = document.querySelectorAll('.skill-badge');
        for (var i = 0; i < skillBadges.length; i++) {
            var badge = skillBadges[i];
            if (badge) {
                var chk = badge.querySelector('input');
                badge.addEventListener('click', function(e) {
                    var chkBox = this.querySelector('input');
                    if (e.target !== chkBox && chkBox) {
                        chkBox.checked = !chkBox.checked;
                    }
                    if (chkBox && chkBox.checked) {
                        this.classList.add('selected');
                    } else if (chkBox) {
                        this.classList.remove('selected');
                    }
                });
                if (chk && chk.checked && badge.classList) {
                    badge.classList.add('selected');
                }
            }
        }

        // Setup form submit
        var form = document.querySelector('form');
        setupFormSubmit(form);

        // Initial step
        showStep(1);
    });
})();
